from __future__ import annotations

import pytest
from pydantic import BaseModel, ValidationError

from llm_router._internal.capabilities.schema import _parse_pydantic_model

pytestmark = pytest.mark.verification_kind("unit")


class Requested(BaseModel):
    answer: int


class Other(BaseModel):
    answer: int


@pytest.mark.verifies("REQ_STRUCTURED_SCHEMA_CONTRACT[revision==2]")
def test_other_model_instance_is_never_returned_as_requested_model() -> None:
    other = Other(answer=7)

    with pytest.raises(ValidationError, match=r"Requested"):
        _parse_pydantic_model(Requested, other)


@pytest.mark.verifies("REQ_STRUCTURED_SCHEMA_CONTRACT[revision==2]")
def test_same_model_instance_is_returned_unchanged() -> None:
    requested = Requested(answer=7)

    assert _parse_pydantic_model(Requested, requested) is requested


@pytest.mark.verifies("REQ_STRUCTURED_SCHEMA_CONTRACT[revision==2]")
def test_valid_json_reconstructs_requested_model() -> None:
    parsed = _parse_pydantic_model(Requested, '{"answer": 7}')

    assert type(parsed) is Requested
    assert parsed.answer == 7
